android.extraProguardRules:
# R8 is on from 1.1.1 (Play: "DEX code optimization below threshold"). It was off from 0.3.0 because
# react-native-android-widget crashed release builds on launch under R8 full mode (AGP 9): R8 stripped the no-arg
# constructors WorkManager/Room create by reflection (github.com/sAleksovski/react-native-android-widget/issues/159).
# Upstream closed it in widget 0.26.0 by moving to work-runtime 2.12.0; we stay on 0.23.0 (patched) and keep these
# rules instead. Gradle is expected to resolve work-runtime to 2.10.5 here (expo-background-task asks for it, the widget
# for 2.8.1), and expo-updates' consumer rules already keep RoomDatabase subclasses' <init>(); these are belt and braces.
# expo-background-task and expo-task-manager run on the same WorkManager (Android, since 1.1.0), so the background
# refresh depends on these rules as much as the widget does: WorkManager persists worker and input merger class names
# and creates them by reflection. Don't trim them.
-keep class androidx.work.impl.WorkDatabase_Impl { <init>(); }
-keep class * extends androidx.room.RoomDatabase { <init>(); }
-keep class * extends androidx.work.InputMerger { <init>(); }
-keep class * extends androidx.work.ListenableWorker { <init>(android.content.Context, androidx.work.WorkerParameters); }
-keep class com.reactnativeandroidwidget.** { *; }
